// Claude 自動レビュー本文の整形ロジック（純関数）。
// workflow の inline JS から切り出し、tests/unit/claude-review-format.test.ts で
// 検証する（#916 round-10 指摘）。伏字化は公開 PR コメントへのシークレット漏洩を
// 防ぐ最後の防波堤のため、変更時は必ずテストを更新すること。

// 既知のトークン形式。GitHub のシークレットマスキングはログにのみ効き、
// API のコメント本文には適用されないため、投稿前に伏字化する。
const SECRET_PATTERN =
  /\b(sk-ant-[A-Za-z0-9_-]{10,}|gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})(?![A-Za-z0-9_-])/g

// issue comment 上限 65536 文字に対して余裕を持つしきい値。
// プロンプトで 6000 字以内を指示しているが出力は強制されないため、
// 実運用に近い値で安全網として機能させる。
export const MAX_BODY_LENGTH = 20000

export function redactSecrets(text) {
  return text.replace(SECRET_PATTERN, '[REDACTED]')
}

// 上限超過時は行単位で切り詰める（サロゲートペアを分割しないようコードポイント
// 単位で数える）。未閉じのコードフェンスは常に判定して補完し、後続のフッターが
// コードブロックに飲み込まれるのを防ぐ。
export function truncateAndCloseFences(text) {
  let result = text
  if (Array.from(result).length > MAX_BODY_LENGTH) {
    const truncated = Array.from(result).slice(0, MAX_BODY_LENGTH).join('')
    const lastNewline = truncated.lastIndexOf('\n')
    result =
      (lastNewline > 0 ? truncated.slice(0, lastNewline) : truncated) +
      '\n\n（長すぎるため省略）'
  }
  // インラインの ``` を誤カウントしないよう、行頭のフェンスのみ数える。
  const fenceCount = result
    .split('\n')
    .filter((line) => line.trim().startsWith('```')).length
  if (fenceCount % 2 === 1) {
    result += '\n```'
  }
  return result
}

// レビュー本文から投稿コメント本文を組み立てる。
export function buildReviewComment({ marker, shortSha, commitUrl, reviewText }) {
  return (
    `${marker}\n## Claude Auto Review\n\n` +
    `Reviewed commit: [\`${shortSha}\`](${commitUrl})\n\n` +
    `${reviewText}\n\n` +
    `*Generated by Claude Code (opus)*`
  )
}
